//! JS and TypeScript generators: `model.gen.js` (path table, enum names, UMD1 decoder) and `model.gen.d.ts`.

use std::fmt::Write as _;

use crate::schema::{Scalar, Schema, Type};

const HEADER: &str =
    "// @generated by `cargo xtask ui gen-model` from `schema/ui-model.toml`. Do not edit.\n";

/// A type as a JSON descriptor: a scalar name, `"key"`, `["enum", N]`, `["struct", N]`, `["opt", d]`,
/// `["list", Elem]`.
fn desc(s: &Schema, ty: &Type) -> String {
    match ty {
        Type::Scalar(sc) => format!("{:?}", sc.name()),
        Type::Key(_) => "\"key\"".into(),
        Type::Enum(e) => format!("[\"enum\",{:?}]", s.enum_def(*e).name),
        Type::Struct(t) => format!("[\"struct\",{:?}]", s.type_def(*t).name),
        Type::Option(inner) => format!("[\"opt\",{}]", desc(s, inner)),
        Type::List(l) => format!("[\"list\",{:?}]", s.type_def(l.elem).name),
    }
}

fn q(s: &str) -> String {
    format!("{s:?}")
}

const DECODER: &str = r#"
function decodeValue(d, v) {
  if (typeof d === "string" || v === null) return v;
  switch (d[0]) {
    case "enum": return ENUMS[d[1]][v];
    case "opt": return decodeValue(d[1], v);
    case "struct": {
      const fields = TYPES[d[1]];
      const o = {};
      for (let i = 0; i < fields.length; i++) o[fields[i][0]] = decodeValue(fields[i][1], v[i]);
      return o;
    }
    case "list": return v.map((e) => decodeValue(["struct", d[1]], e[1]));
    default: throw new Error("bad type descriptor " + JSON.stringify(d));
  }
}

const PATH_IDS = new Map(PATHS.map((p, i) => [p.path, i]));

/** The field id of a path such as `top.gold` or `top.resources[].name`, or -1. */
export function fieldId(path) {
  const id = PATH_IDS.get(path);
  return id === undefined ? -1 : id;
}

/**
 * Decode a UMD1 text (a frame delta or a snapshot) into `{revision, ops}`. Ops are objects with `op` one of
 * `set`, `insert`, `remove`, `move`, `reset`; values are decoded by the schema (structs to objects, enums to
 * names, lists to arrays of elements). Throws if the text was built for another schema.
 */
export function decodeUmd1(text) {
  const a = JSON.parse(text);
  const ops = [];
  for (let i = 1; i < a.length; i++) {
    const o = a[i];
    switch (o[0]) {
      case 0: {
        const p = PATHS[o[1]];
        ops.push({ op: "set", field: o[1], path: p.path, keys: o[2], value: decodeValue(p.type, o[3]) });
        break;
      }
      case 1: {
        const p = PATHS[o[1]];
        ops.push({ op: "insert", field: o[1], path: p.path, keys: o[2], at: o[3], key: o[4],
          value: decodeValue(["struct", p.type[1]], o[5]) });
        break;
      }
      case 2: {
        const p = PATHS[o[1]];
        ops.push({ op: "remove", field: o[1], path: p.path, keys: o[2], key: o[3] });
        break;
      }
      case 3: {
        const p = PATHS[o[1]];
        ops.push({ op: "move", field: o[1], path: p.path, keys: o[2], key: o[3], to: o[4] });
        break;
      }
      case 4:
        ops.push({ op: "reset", root: ROOTS[o[1]][0], value: decodeValue(ROOTS[o[1]][1], o[2]) });
        break;
      case 5:
        if (o[1] !== SCHEMA_HASH) {
          throw new Error("model schema mismatch: delta " + o[1] + ", client " + SCHEMA_HASH);
        }
        break;
      default:
        throw new Error("unknown UMD1 op " + o[0]);
    }
  }
  return { revision: a[0], ops };
}
"#;

/// The text of `apps/web/www/ui2/model.gen.js`.
pub fn generate_js(s: &Schema) -> String {
    let mut out = String::from(HEADER);
    let _ = writeln!(
        out,
        "export const SCHEMA_VERSION = {};",
        q(&s.version().to_string())
    );
    let _ = writeln!(out, "export const SCHEMA_HASH = \"{:016x}\";", s.hash());
    out.push_str("\n/** Roots in schema order: `[name, type descriptor of the whole root]`. The index is the root id of a `reset` op. */\nexport const ROOTS = [\n");
    for r in s.roots() {
        let _ = writeln!(out, "  [{}, {}],", q(&r.name), desc(s, &r.value_type()));
    }
    out.push_str(
        "];\n\n/** Enum variant names; a value is the index. */\nexport const ENUMS = {\n",
    );
    for e in s.enums() {
        let names: Vec<String> = e.variants.iter().map(|v| q(v)).collect();
        let _ = writeln!(out, "  {}: [{}],", q(&e.name), names.join(", "));
    }
    out.push_str("};\n\n/** Struct types: `[field name, type descriptor]` in field order. */\nexport const TYPES = {\n");
    for t in s.types() {
        let fields: Vec<String> = t
            .fields
            .iter()
            .map(|f| format!("[{}, {}]", q(&f.name), desc(s, &f.ty)))
            .collect();
        let _ = writeln!(out, "  {}: [{}],", q(&t.name), fields.join(", "));
    }
    out.push_str("};\n\n/** The path table; the index is the field id used in deltas. */\nexport const PATHS = [\n");
    for p in s.paths() {
        let mut row = format!("{{ path: {}, type: {}", q(&p.path), desc(s, &p.ty));
        if let Some(k) = &p.list_key {
            let _ = write!(row, ", key: {}", q(k));
        }
        if p.js {
            row.push_str(", js: true");
        }
        row.push_str(" },");
        let _ = writeln!(out, "  {row}");
    }
    out.push_str("];\n");
    out.push_str(DECODER);
    out
}

fn ts_type(s: &Schema, ty: &Type) -> String {
    match ty {
        Type::Scalar(sc) => match sc {
            Scalar::Bool => "boolean".into(),
            Scalar::I8 | Scalar::I16 | Scalar::I32 | Scalar::U32 | Scalar::F32 | Scalar::Color => {
                "number".into()
            }
            Scalar::Str | Scalar::Asset => "string".into(),
            Scalar::Text => "Text".into(),
        },
        Type::Key(_) => "Key".into(),
        Type::Enum(e) => s.enum_def(*e).name.clone(),
        Type::Struct(t) => s.type_def(*t).name.clone(),
        Type::Option(inner) => format!("{} | null", ts_type(s, inner)),
        Type::List(l) => format!("{}[]", s.type_def(l.elem).name),
    }
}

const DTS_FOOT: &str = r#"
/** A decoded operation of a frame delta. Values follow the types above. */
export type DeltaOp =
  | { op: "set"; field: number; path: string; keys: Key[]; value: unknown }
  | { op: "insert"; field: number; path: string; keys: Key[]; at: number; key: Key; value: unknown }
  | { op: "remove"; field: number; path: string; keys: Key[]; key: Key }
  | { op: "move"; field: number; path: string; keys: Key[]; key: Key; to: number }
  | { op: "reset"; root: keyof Model; value: unknown };

export interface Delta {
  revision: number;
  ops: DeltaOp[];
}

export const SCHEMA_VERSION: string;
export const SCHEMA_HASH: string;
export const ROOTS: [string, unknown][];
export const ENUMS: Record<string, string[]>;
export const TYPES: Record<string, [string, unknown][]>;
export const PATHS: { path: string; type: unknown; key?: string; js?: true }[];
export function fieldId(path: string): number;
export function decodeUmd1(text: string): Delta;
"#;

/// The text of `apps/web/www/ui2/model.gen.d.ts`.
pub fn generate_dts(s: &Schema) -> String {
    let mut out = String::from(HEADER);
    out.push_str("\n/** A stable entity key: `\"hi:lo\"` (a u64 does not fit a number). */\nexport type Key = string;\n");
    out.push_str("/** Text: ready text, or a localisation key with arguments. */\nexport type Text = string | { k: string; a: string[] };\n\n");
    for e in s.enums() {
        let vs: Vec<String> = e.variants.iter().map(|v| q(v)).collect();
        let _ = writeln!(out, "export type {} = {};", e.name, vs.join(" | "));
    }
    out.push('\n');
    for t in s.types() {
        let _ = writeln!(out, "export interface {} {{", t.name);
        for f in &t.fields {
            let _ = writeln!(out, "  readonly {}: {};", f.name, ts_type(s, &f.ty));
        }
        out.push_str("}\n\n");
    }
    out.push_str("/** The model: one member per root. */\nexport interface Model {\n");
    for r in s.roots() {
        let _ = writeln!(
            out,
            "  readonly {}: {};",
            r.name,
            ts_type(s, &r.value_type())
        );
    }
    out.push_str("}\n");
    out.push_str(DTS_FOOT);
    out
}
